// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time1, uint256 time2) public {
        time1 = bound(time1, 1, 1e18);
        time2 = bound(time2, 1, 1e18);
        vm.assume(time2 <= time1); // second call at same or earlier timestamp

        vm.deal(address(this), 20 ether);
        vm.warp(time1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        vm.warp(time2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1 && !ok2);
    }
}

